import '../helpers/runtime-workspace.mjs';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import JSZip from 'jszip';
import sharp from 'sharp';
import { loadManifest, repositoryRoot } from '../../lib/workbench/runtime.mjs';
import { inspectAssetPackage, commitAssetPackages, readAssetPackagePreview } from '../../lib/workbench/asset-packages.mjs';
import { buildAssetArchive, buildAssetImport, getAsset } from '../../lib/workbench/asset-catalog.mjs';

// Generated by generate-object-export-fixture.py using the production exporter.
const bytes = await readFile(new URL('./fixtures/interactable-animation.zip', import.meta.url));
const source = await JSZip.loadAsync(bytes);
const contractPath = Object.keys(source.files).find(name => name.endsWith('/export.json'));
const contract = JSON.parse(await source.file(contractPath).async('string'));
assert.equal(contract.object_type, 'interactable');
assert.equal(Object.hasOwn(contract, 'source_facing'), false);
const manifest = await loadManifest();
manifest.workspace.importedAssetDirectory += '/object-animation';
manifest.workspace.packageImportDirectory += '/object-animation';
Object.assign(manifest.capabilities.find(item => item.id === 'sprite-generator').connector, {
  urlEnv: 'OBJECT_ANIMATION_TEST_UNUSED_URL', defaultUrl: 'http://127.0.0.1:1',
});
const inspect = data => inspectAssetPackage(repositoryRoot, manifest, { bytes: data, filename: 'interactable-animation.zip' });
const inspection = await inspect(bytes);
const candidate = inspection.candidates[0];
assert.notEqual(candidate.status, 'incomplete', JSON.stringify(candidate));
assert.equal(candidate.metadata.objectId, 'fixture_door');
assert.equal(candidate.metadata.objectType, 'interactable');
assert.equal(Object.hasOwn(candidate.metadata, 'sourceFacing'), false);
const preview = await readAssetPackagePreview(repositoryRoot, manifest, { inspectionId: inspection.inspectionId, candidateId: candidate.id });
const sheet = await source.file(contractPath.replace(/export\.json$/, 'sprite-sheet.png')).async('nodebuffer');
assert.deepEqual(await sharp(preview.bytes).raw().toBuffer(), await sharp(sheet).extract({ left: 0, top: 0, width: 128, height: 128 }).raw().toBuffer());
const committed = await commitAssetPackages(repositoryRoot, manifest, {
  commandId: 'object-animation-fixture', selections: [{ inspectionId: inspection.inspectionId, candidateId: candidate.id }],
});
const asset = (await getAsset(manifest, { assetId: committed.assets[0].id })).asset;
assert.equal(asset.objectId, 'fixture_door');
assert.equal(asset.objectType, 'interactable');
const imported = await JSZip.loadAsync((await buildAssetImport(manifest, { assetId: asset.id, revision: asset.revision, purpose: 'animation' })).bytes);
const importInfo = JSON.parse(await imported.file('import.json').async('string'));
assert.equal(importInfo.asset.objectId, 'fixture_door');
assert.equal(importInfo.asset.objectType, 'interactable');
assert.equal(Object.hasOwn(importInfo.asset, 'sourceFacing'), false);

const archive = await buildAssetArchive(manifest, { assetIds: [asset.id] });
const roundtrip = await inspect(archive.bytes);
const recovered = roundtrip.candidates[0];
assert.notEqual(recovered.status, 'incomplete', JSON.stringify(recovered));
assert.equal(recovered.metadata.objectId, 'fixture_door');
assert.equal(recovered.metadata.objectType, 'interactable');
assert.deepEqual(recovered.metadata.animationRepresentations.map(item => item.representation), ['frames', 'sheet']);
for (const representation of recovered.metadata.animationRepresentations) {
  assert.equal(representation.objectId, 'fixture_door');
  assert.equal(representation.objectType, 'interactable');
  assert.equal(Object.hasOwn(representation, 'sourceFacing'), false);
}
const reused = await commitAssetPackages(repositoryRoot, manifest, {
  commandId: 'object-animation-roundtrip', selections: [{ inspectionId: roundtrip.inspectionId, candidateId: recovered.id }],
});
assert.equal(reused.reusedCount, 1);

async function changedContract(change) {
  const zip = await JSZip.loadAsync(bytes), next = structuredClone(contract);
  change(next);
  zip.file(contractPath, JSON.stringify(next));
  return inspect(await zip.generateAsync({ type: 'nodebuffer' }));
}
for (const change of [
  value => { delete value.object_id; delete value.object_type; },
  value => { delete value.object_id; delete value.object_type; value.source_facing = 'up'; },
  value => { value.object_type = 'character'; },
  value => { value.source_facing = 'left'; },
  value => { value.object_id = '../door'; },
  value => { value.character_id = 'different_door'; },
  value => { value.object_type = 'unsupported'; },
]) assert.equal((await changedContract(change)).candidates[0].status, 'incomplete');
assert.notEqual((await changedContract(value => { value.object_type = 'character'; value.source_facing = 'right'; })).candidates[0].status, 'incomplete');
assert.notEqual((await changedContract(value => { delete value.object_id; delete value.object_type; value.source_facing = 'left'; })).candidates[0].status, 'incomplete');

const wrongObject = await JSZip.loadAsync(archive.bytes);
const archiveManifest = JSON.parse(await wrongObject.file('forge-assets.json').async('string'));
archiveManifest.entries[0].metadata.objectId = 'different_door';
wrongObject.file('forge-assets.json', JSON.stringify(archiveManifest));
const mismatch = (await inspect(await wrongObject.generateAsync({ type: 'nodebuffer' }))).candidates[0];
assert(mismatch.warnings.some(message => message.includes('不同对象')));
assert.equal(mismatch.metadata.animationRepresentations.some(item => item.representation === 'sheet'), false);
console.log('Typed object animation import passed: actual SpriteFrames export, exact sheet pixels, raw/sheet roundtrip identity, reuse, and strict character-facing/alias guards.');
